#include <vector>
#include <queue>
#include <tuple>

class Solution {
public:
    int minCostPathWithKTurns(std::vector<std::vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        int dirs[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

        // cost, r, c, dir, turns
        typedef std::tuple<int, int, int, int, int> State;
        std::priority_queue<State, std::vector<State>, std::greater<State>> pq;

        std::vector<std::vector<std::vector<std::vector<int>>>> dist(
            m, std::vector<std::vector<std::vector<int>>>(
                n, std::vector<std::vector<int>>(4, std::vector<int>(k + 1, 1e9))));

        for (int d = 0; d < 4; ++d) {
            pq.push({grid[0][0], 0, 0, d, 0});
            dist[0][0][d][0] = grid[0][0];
        }

        while (!pq.empty()) {
            auto [cost, r, c, d, turns] = pq.top();
            pq.pop();

            if (r == m - 1 && c == n - 1) return cost;
            if (cost > dist[r][c][d][turns]) continue;

            for (int nd = 0; nd < 4; ++nd) {
                int nr = r + dirs[nd][0];
                int nc = c + dirs[nd][1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int nturns = turns + (nd != d ? 1 : 0);
                    if (nturns <= k) {
                        int ncost = cost + grid[nr][nc];
                        if (ncost < dist[nr][nc][nd][nturns]) {
                            dist[nr][nc][nd][nturns] = ncost;
                            pq.push({ncost, nr, nc, nd, nturns});
                        }
                    }
                }
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minCostPathWithKTurns(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        int[][] dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        int[][][][] dist = new int[m][n][4][k + 1];
        for (int[][][] d1 : dist) {
            for (int[][] d2 : d1) {
                for (int[] d3 : d2) Arrays.fill(d3, Integer.MAX_VALUE);
            }
        }

        for (int d = 0; d < 4; d++) {
            pq.offer(new int[]{grid[0][0], 0, 0, d, 0});
            dist[0][0][d][0] = grid[0][0];
        }

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int cost = top[0], r = top[1], c = top[2], d = top[3], turns = top[4];

            if (r == m - 1 && c == n - 1) return cost;
            if (cost > dist[r][c][d][turns]) continue;

            for (int nd = 0; nd < 4; nd++) {
                int nr = r + dirs[nd][0];
                int nc = c + dirs[nd][1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int nturns = turns + (nd != d ? 1 : 0);
                    if (nturns <= k) {
                        int ncost = cost + grid[nr][nc];
                        if (ncost < dist[nr][nc][nd][nturns]) {
                            dist[nr][nc][nd][nturns] = ncost;
                            pq.offer(new int[]{ncost, nr, nc, nd, nturns});
                        }
                    }
                }
            }
        }
        return -1;
    }
}

function minCostPathWithKTurns(grid, k) {
    const m = grid.length, n = grid[0].length;
    const dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]];

    // simple priority queue / min-heap or sorted array for moderate k
    const pq = [];
    function pushState(item) {
        pq.push(item);
        pq.sort((a, b) => a[0] - b[0]);
    }

    const dist = new Map();
    for (let d = 0; d < 4; d++) {
        pushState([grid[0][0], 0, 0, d, 0]);
        dist.set(`0,0,${d},0`, grid[0][0]);
    }

    while (pq.length > 0) {
        const [cost, r, c, d, turns] = pq.shift();
        if (r === m - 1 && c === n - 1) return cost;

        const stateKey = `${r},${c},${d},${turns}`;
        if (cost > (dist.get(stateKey) ?? Infinity)) continue;

        for (let nd = 0; nd < 4; nd++) {
            const nr = r + dirs[nd][0];
            const nc = c + dirs[nd][1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                const nturns = turns + (nd !== d ? 1 : 0);
                if (nturns <= k) {
                    const ncost = cost + grid[nr][nc];
                    const nextKey = `${nr},${nc},${nd},${nturns}`;
                    if (ncost < (dist.get(nextKey) ?? Infinity)) {
                        dist.set(nextKey, ncost);
                        pushState([ncost, nr, nc, nd, nturns]);
                    }
                }
            }
        }
    }
    return -1;
}
